func Test_CUE(t *testing.T) {
	ctx := cuecontext.New()

	schemaBytes, err := os.ReadFile("flipt.schema.cue")
	require.NoError(t, err)

	v := ctx.CompileBytes(schemaBytes)

	conf := defaultConfig(t)

	dflt := ctx.Encode(conf)

	err = v.LookupPath(cue.MakePath(cue.Def("#FliptSpec"))).Unify(dflt).Validate(
		cue.Concrete(true),
	)

	if errs := errors.Errors(err); len(errs) > 0 {
		for _, err := range errs {
			t.Log(err)
		}
		t.Fatal("Errors validating CUE schema against default configuration")
	}
}

func adapt(m map[string]any) {
	for k, v := range m {
		switch t := v.(type) {
		case map[string]any:
			adapt(t)
		case time.Duration:
			m[k] = t.String()
		}
	}
}

func Test_JSONSchema(t *testing.T) {
	schemaBytes, err := os.ReadFile("flipt.schema.json")
	require.NoError(t, err)

	schema := gojsonschema.NewBytesLoader(schemaBytes)

	conf := defaultConfig(t)
	res, err := gojsonschema.Validate(schema, gojsonschema.NewGoLoader(conf))
	require.NoError(t, err)

	if !assert.True(t, res.Valid(), "Schema is invalid") {
		for _, err := range res.Errors() {
			t.Log(err)
		}
	}
}

func defaultConfig(t *testing.T) (conf map[string]any) {
	dec, err := mapstructure.NewDecoder(&mapstructure.DecoderConfig{
		DecodeHook: mapstructure.ComposeDecodeHookFunc(config.DecodeHooks...),
		Result:     &conf,
	})
	require.NoError(t, err)
	require.NoError(t, dec.Decode(config.Default()))

	// adapt converts instances of time.Duration to their
	// string representation, which CUE is going to validate
	adapt(conf)

	return
}

// It returns a Bundle which contains metadata regarding the resulting bundle details
func (s *Store) Build(ctx context.Context, src fs.FS, ref Reference) (Bundle, error) {
	store, err := s.getTarget(ref)
	if err != nil {
		return Bundle{}, err
	}

	layers, err := s.buildLayers(ctx, store, src)
	if err != nil {
		return Bundle{}, err
	}

	desc, err := oras.PackManifest(ctx, store, oras.PackManifestVersion1_1_RC4, MediaTypeFliptFeatures, oras.PackManifestOptions{
		ManifestAnnotations: map[string]string{},
		Layers:              layers,
	})
	if err != nil {
		return Bundle{}, err
	}

	if ref.Reference.Reference != "" {
		if err := store.Tag(ctx, desc, ref.Reference.Reference); err != nil {
			return Bundle{}, err
		}
	}

	bundle := Bundle{
		Digest:     desc.Digest,
		Repository: ref.Repository,
		Tag:        ref.Reference.Reference,
	}

	bundle.CreatedAt, err = parseCreated(desc.Annotations)
	if err != nil {
		return Bundle{}, err
	}

	return bundle, nil
}

func (s *Store) buildLayers(ctx context.Context, store oras.Target, src fs.FS) (layers []v1.Descriptor, _ error) {
	if err := storagefs.WalkDocuments(s.logger, src, func(doc *ext.Document) error {
		payload, err := json.Marshal(&doc)
		if err != nil {
			return err
		}

		desc := v1.Descriptor{
			Digest:    digest.FromBytes(payload),
			Size:      int64(len(payload)),
			MediaType: MediaTypeFliptNamespace,
			Annotations: map[string]string{
				AnnotationFliptNamespace: doc.Namespace,
			},
